.sl-hero-wrapper {
  --sl-bg: var(--smartlearn-bg);
  --sl-surface: var(--smartlearn-card-bg);
  --sl-surface-hover: color-mix(in srgb, var(--smartlearn-primary) 10%, var(--smartlearn-card-bg));
  --sl-border: var(--smartlearn-card-border);
  --sl-text-main: var(--smartlearn-text);
  --sl-text-muted: var(--smartlearn-text-muted);
  --sl-primary: var(--smartlearn-primary);
  --sl-btn-bg: var(--smartlearn-btn-bg);
  --sl-btn-hover: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  --sl-btn-text: var(--smartlearn-btn-text, #ffffff);
  --sl-radius: var(--smartlearn-radius, 16px);
  --sl-font: var(--smartlearn-body-font, system-ui, -apple-system, sans-serif);
  --sl-heading: var(--smartlearn-heading-font, var(--smartlearn-body-font, system-ui, -apple-system, sans-serif));
  position: relative;
  width: 100%;
  min-height: 85vh;
  background-color: var(--sl-bg);
  color: var(--sl-text-main);
  font-family: var(--sl-font);
  overflow: hidden;
  padding: clamp(3rem, 6vw, 5rem) 1.5rem;
  display: flex;
  align-items: center;
  box-sizing: border-box;
}
.sl-hero-wrapper *,
.sl-hero-wrapper *::before,
.sl-hero-wrapper *::after {
  box-sizing: inherit;
}
.sl-hero-wrapper .sl-ambient-light {
  position: absolute;
  width: 480px;
  height: 480px;
  border-radius: 50%;
  filter: blur(130px);
  opacity: 0.16;
  pointer-events: none;
  z-index: 0;
}
.sl-hero-wrapper .sl-ambient-indigo {
  top: -10%;
  inset-inline-start: -5%;
  background: radial-gradient(circle, var(--sl-primary), transparent 70%);
}
.sl-hero-wrapper .sl-ambient-cyan {
  bottom: -15%;
  inset-inline-end: 5%;
  background: radial-gradient(circle, var(--sl-text-muted), transparent 70%);
}
.sl-hero-wrapper .sl-hero-container {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 3.5rem;
  align-items: center;
}
.sl-hero-wrapper .sl-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: var(--sl-surface);
  border: 1px solid var(--sl-border);
  border-radius: 100px;
  font-size: 0.825rem;
  font-weight: 600;
  color: var(--sl-text-main);
  margin-bottom: 1.5rem;
}
.sl-hero-wrapper .sl-badge-indicator,
.sl-hero-wrapper .sl-status-dot {
  width: 8px;
  height: 8px;
  background: var(--sl-primary);
  border-radius: 50%;
}
.sl-hero-wrapper .sl-hero-title {
  font-family: var(--sl-heading);
  font-size: clamp(2.4rem, 4.5vw, 3.85rem);
  font-weight: 800;
  line-height: 1.12;
  letter-spacing: -0.03em;
  margin: 0 0 1.25rem 0;
  color: var(--sl-text-main);
}
.sl-hero-wrapper .sl-title-gradient {
  color: var(--sl-primary);
}
.sl-hero-wrapper .sl-hero-subtitle {
  font-size: 1.125rem;
  line-height: 1.65;
  color: var(--sl-text-muted);
  margin: 0 0 2rem 0;
  max-width: 92%;
}
.sl-hero-wrapper .sl-feature-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-bottom: 2.25rem;
}
.sl-hero-wrapper .sl-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0.65rem 1.15rem;
  background: var(--sl-surface);
  border: 1px solid var(--sl-border);
  border-radius: 100px;
  color: var(--sl-text-muted);
  font-family: inherit;
  font-size: 0.875rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}
.sl-hero-wrapper .sl-pill:hover,
.sl-hero-wrapper .sl-pill.active {
  background: var(--sl-surface-hover);
  border-color: var(--sl-primary);
  color: var(--sl-text-main);
}
.sl-hero-wrapper .sl-svg-icon {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
}
.sl-hero-wrapper .sl-cta-group {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 3rem;
}
.sl-hero-wrapper .sl-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 0.9rem 1.8rem;
  border-radius: var(--sl-radius);
  font-size: 0.95rem;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  transition: transform 0.2s ease, background-color 0.2s ease, border-color 0.2s ease;
  border: 1px solid transparent;
}
.sl-hero-wrapper .sl-btn-primary {
  background: var(--sl-btn-bg);
  border-color: var(--sl-btn-bg);
  color: var(--sl-btn-text);
}
.sl-hero-wrapper .sl-btn-primary:hover,
.sl-hero-wrapper .sl-btn-primary:focus-visible {
  background: var(--sl-btn-hover);
  border-color: var(--sl-btn-hover);
  color: var(--sl-btn-text);
}
.sl-hero-wrapper .sl-btn-outline {
  background: var(--sl-surface);
  border-color: var(--sl-primary);
  color: var(--sl-primary);
}
.sl-hero-wrapper .sl-btn-outline:hover,
.sl-hero-wrapper .sl-btn-outline:focus-visible {
  background: var(--sl-btn-bg);
  border-color: var(--sl-btn-bg);
  color: var(--sl-btn-text);
}
.sl-hero-wrapper .sl-stat-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 2rem;
  padding-top: 2rem;
  border-top: 1px solid var(--sl-border);
}
.sl-hero-wrapper .sl-stat-box {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.sl-hero-wrapper .sl-stat-value {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--sl-text-main);
  line-height: 1;
}
.sl-hero-wrapper .sl-stat-label {
  font-size: 0.825rem;
  color: var(--sl-text-muted);
  font-weight: 500;
}
.sl-hero-wrapper .sl-stat-divider {
  width: 1px;
  height: 36px;
  background: var(--sl-border);
}
.sl-hero-wrapper .sl-hero-preview {
  perspective: 1000px;
}
.sl-hero-wrapper .sl-hero-uploaded-wrapper {
  text-align: center;
}
.sl-hero-wrapper .sl-showcase-img {
  max-width: 100%;
  height: auto;
  border-radius: var(--sl-radius);
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.2);
  border: 1px solid var(--sl-border);
}
.sl-hero-wrapper .sl-interactive-card {
  background: var(--sl-surface);
  border: 1px solid var(--sl-border);
  border-radius: 20px;
  padding: 1.5rem;
  box-shadow: 0 20px 45px -12px rgba(0, 0, 0, 0.22);
  transition: transform 0.25s ease;
}
.sl-hero-wrapper .sl-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--sl-border);
  margin-bottom: 1rem;
}
.sl-hero-wrapper .sl-card-identity {
  display: flex;
  align-items: center;
  gap: 12px;
}
.sl-hero-wrapper .sl-identity-icon {
  width: 42px;
  height: 42px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--sl-primary) 15%, transparent);
  border: 1px solid color-mix(in srgb, var(--sl-primary) 35%, transparent);
  color: var(--sl-primary);
  display: flex;
  align-items: center;
  justify-content: center;
}
.sl-hero-wrapper .sl-card-title-dynamic {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--sl-text-main);
}
.sl-hero-wrapper .sl-card-status {
  font-size: 0.75rem;
  color: var(--sl-text-muted);
  display: flex;
  align-items: center;
  gap: 6px;
}
.sl-hero-wrapper .sl-card-tag-dynamic {
  font-size: 0.75rem;
  font-weight: 600;
  padding: 4px 10px;
  background: var(--sl-surface-hover);
  border: 1px solid var(--sl-border);
  color: var(--sl-text-main);
  border-radius: 100px;
}
.sl-hero-wrapper .sl-messages-list-dynamic {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
  margin-bottom: 1rem;
}
.sl-hero-wrapper .sl-msg {
  display: flex;
  flex-direction: column;
  max-width: 88%;
}
.sl-hero-wrapper .sl-msg-ai { align-self: flex-start; }
.sl-hero-wrapper .sl-msg-user { align-self: flex-end; }
.sl-hero-wrapper .sl-msg-bubble {
  padding: 0.8rem 1rem;
  border-radius: 14px;
  font-size: 0.9rem;
  line-height: 1.5;
}
.sl-hero-wrapper .sl-msg-ai .sl-msg-bubble {
  background: var(--sl-bg);
  border: 1px solid var(--sl-border);
  color: var(--sl-text-main);
  border-end-start-radius: 4px;
}
.sl-hero-wrapper .sl-msg-user .sl-msg-bubble {
  background: var(--sl-btn-bg);
  color: var(--sl-btn-text);
  border-end-end-radius: 4px;
}
.sl-hero-wrapper .sl-prompt-chips {
  border-top: 1px solid var(--sl-border);
  padding-top: 1rem;
}
.sl-hero-wrapper .sl-chip-label {
  display: block;
  font-size: 0.75rem;
  color: var(--sl-text-muted);
  margin-bottom: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 600;
}
.sl-hero-wrapper .sl-chips-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.sl-hero-wrapper .sl-chip-btn {
  background: var(--sl-bg);
  border: 1px solid var(--sl-border);
  color: var(--sl-text-main);
  padding: 0.5rem 0.85rem;
  border-radius: 8px;
  font-family: inherit;
  font-size: 0.8rem;
  cursor: pointer;
  transition: background-color 0.2s ease, border-color 0.2s ease;
}
.sl-hero-wrapper .sl-chip-btn:hover,
.sl-hero-wrapper .sl-chip-btn:focus-visible {
  background: var(--sl-surface-hover);
  border-color: var(--sl-primary);
}
.sl-hero-wrapper .sl-pill:focus-visible,
.sl-hero-wrapper .sl-chip-btn:focus-visible,
.sl-hero-wrapper .sl-btn:focus-visible {
  outline: 2px solid var(--sl-primary);
  outline-offset: 2px;
}
[dir="rtl"] .sl-hero-wrapper .sl-rtl-flip {
  transform: scaleX(-1);
}
@media (prefers-reduced-motion: no-preference) {
  .sl-hero-wrapper .sl-msg {
    animation: sl-hero-split-01-slide 0.25s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  }
  .sl-hero-wrapper .sl-btn:hover {
    transform: translateY(-2px);
  }
}
@media (prefers-reduced-motion: reduce) {
  .sl-hero-wrapper .sl-pill,
  .sl-hero-wrapper .sl-btn,
  .sl-hero-wrapper .sl-interactive-card,
  .sl-hero-wrapper .sl-chip-btn {
    transition: none;
  }
}
@keyframes sl-hero-split-01-slide {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
@media (max-width: 992px) {
  .sl-hero-wrapper .sl-hero-container {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }
  .sl-hero-wrapper .sl-stat-bar {
    gap: 1.25rem;
  }
}

