(function() {
  'use strict';
  function initSmartLearnHero() {
    var heroes = document.querySelectorAll('.sl-hero-wrapper');
    if (!heroes.length) return;
    var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    heroes.forEach(function(hero) {
      if (hero.dataset.slInit === '1') return;
      hero.dataset.slInit = '1';
      var pills = Array.prototype.slice.call(hero.querySelectorAll('.sl-pill'));
      var cardTitle = hero.querySelector('.sl-card-title-dynamic');
      var cardTag = hero.querySelector('.sl-card-tag-dynamic');
      var messageList = hero.querySelector('.sl-messages-list-dynamic');
      var replyTimer = null;
      var tabData = {
        tutor: {
          title: 'AI Tutor Neural Copilot',
          tag: 'GPT-4o Adaptive',
          initialMsg: "Hello! I've monitored your progress in Advanced Calculus. How can I assist your study session today?"
        },
        path: {
          title: 'Adaptive Learning Path',
          tag: 'Real-time Curriculum',
          initialMsg: 'Your diagnostic quiz indicates high proficiency in Linear Algebra. Module 4: Matrix Transformations is now unlocked.'
        },
        analytics: {
          title: 'Predictive Exam Engine',
          tag: '99.4% Accuracy',
          initialMsg: 'Based on your current retention curve, your projected final score is 94% (Grade A). Keep reviewing weekly flashcards!'
        }
      };
      function appendBubble(roleClass, text) {
        if (!messageList) return;
        var msg = document.createElement('div');
        msg.className = 'sl-msg ' + roleClass;
        var bubble = document.createElement('div');
        bubble.className = 'sl-msg-bubble';
        bubble.textContent = text;
        msg.appendChild(bubble);
        messageList.appendChild(msg);
      }
      function activatePill(pill) {
        pills.forEach(function(p) {
          p.classList.remove('active');
          p.setAttribute('aria-selected', 'false');
        });
        pill.classList.add('active');
        pill.setAttribute('aria-selected', 'true');
        if (replyTimer) {
          window.clearTimeout(replyTimer);
          replyTimer = null;
        }
        var key = pill.getAttribute('data-tab');
        var data = tabData[key];
        if (data && cardTitle && cardTag && messageList) {
          cardTitle.textContent = data.title;
          cardTag.textContent = data.tag;
          while (messageList.firstChild) messageList.removeChild(messageList.firstChild);
          appendBubble('sl-msg-ai', data.initialMsg);
        }
      }
      pills.forEach(function(pill, idx) {
        pill.addEventListener('click', function() { activatePill(pill); });
        pill.addEventListener('keydown', function(e) {
          if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
            e.preventDefault();
            var step = e.key === 'ArrowRight' ? 1 : -1;
            var next = pills[(idx + step + pills.length) % pills.length];
            next.focus();
            activatePill(next);
          }
        });
      });
      hero.querySelectorAll('.sl-chip-btn').forEach(function(btn) {
        btn.addEventListener('click', function() {
          var visibleText = (btn.textContent || '').trim();
          var promptText = visibleText || btn.getAttribute('data-prompt') || '';
          if (!promptText || !messageList) return;
          appendBubble('sl-msg-user', promptText);
          if (replyTimer) window.clearTimeout(replyTimer);
          replyTimer = window.setTimeout(function() {
            var lower = promptText.toLowerCase();
            var reply = "I'm analyzing your request and generating a tailored practice module right now.";
            if (lower.indexOf('quiz') !== -1) {
              reply = 'Question 1 of 3: What is the integral of x * e^x dx?';
            } else if (lower.indexOf('study') !== -1) {
              reply = "I've structured a 45-minute daily schedule targeting Series & Limits.";
            } else if (lower.indexOf('summarize') !== -1) {
              reply = "Summary: Today's lecture covered Taylor Polynomials and Lagrange error bounds.";
            }
            appendBubble('sl-msg-ai', reply);
          }, 350);
        });
      });
      var counters = hero.querySelectorAll('.sl-stat-value');
      var animated = false;
      function animateCounters() {
        if (animated || reduceMotion) return;
        animated = true;
        counters.forEach(function(counter) {
          var target = parseInt(counter.getAttribute('data-target') || '0', 10);
          var suffix = counter.getAttribute('data-suffix') || '';
          if (!target) return;
          var current = 0;
          var increment = Math.max(1, Math.floor(target / 25));
          var interval = window.setInterval(function() {
            current += increment;
            if (current >= target) {
              current = target;
              window.clearInterval(interval);
            }
            counter.textContent = current + suffix;
          }, 25);
        });
      }
      if ('IntersectionObserver' in window && !reduceMotion) {
        var observer = new IntersectionObserver(function(entries) {
          if (entries[0] && entries[0].isIntersecting) {
            animateCounters();
            observer.disconnect();
          }
        }, { threshold: 0.3 });
        observer.observe(hero);
      }
      var card = hero.querySelector('.sl-interactive-card');
      if (card && !reduceMotion && window.innerWidth > 992) {
        card.addEventListener('mousemove', function(e) {
          var rect = card.getBoundingClientRect();
          var rx = Math.max(-6, Math.min(6, ((e.clientY - rect.top - rect.height / 2) / rect.height) * -12));
          var ry = Math.max(-6, Math.min(6, ((e.clientX - rect.left - rect.width / 2) / rect.width) * 12));
          card.style.transform = 'rotateY(' + ry.toFixed(2) + 'deg) rotateX(' + rx.toFixed(2) + 'deg)';
        });
        card.addEventListener('mouseleave', function() {
          card.style.transform = 'rotateY(0deg) rotateX(0deg)';
        });
      }
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initSmartLearnHero);
  } else {
    initSmartLearnHero();
  }
})();
